H.background();
// Friction:  f_s ≤ μ_s N,  f_k = μ_k N,   N = mg on a flat floor.
// You push a block harder and harder. Static friction matches the push until it
// hits f_s,max; then the block breaks free and slides under kinetic friction
// (smaller, so it lurches forward). The whole cycle loops.
const g = 9.8;
const m = Math.max(0.1, P.m);
const muS = Math.max(0, P.muS);
const muK = Math.max(0, Math.min(P.muK, muS));   // kinetic ≤ static, physically
const N = m * g;
const fsMax = muS * N, fk = muK * N;
const v = H.plot2d({ xMin: 0, xMax: 10, yMin: -1, yMax: 6, box: { x: 50, y: 70, w: H.W - 100, h: H.H - 150 } });
v.line(0, 0, 10, 0, { color: H.colors.axis, width: 3 });
for (let i = 0; i < 22; i++) v.line(i * 0.5, 0, i * 0.5 - 0.35, -0.6, { color: H.colors.grid, width: 1.5 });
// applied push ramps 0 → 2·f_s,max over an 8s loop
const phase = (t * 0.8) % 8;
const Fapp = phase * fsMax / 4;
const sliding = Fapp > fsMax + 1e-9;
const friction = sliding ? fk : Math.min(Fapp, fsMax);
// block: parked at x=2 until it breaks free, then slides forward (bounded)
let bx = 2;
if (sliding) bx = 2 + 4 * (phase - 4) / 4;
bx = Math.max(1.5, Math.min(8, bx));
const bw = 1.2, bh = 1.0, cy = bh / 2;
v.rect(bx - bw / 2, 0, bw, bh, { fill: H.colors.panel, stroke: H.colors.accent, width: 2 });
v.text("m", bx, cy, { color: H.colors.ink, size: 14, align: "center" });
// applied push (blue, right), friction (orange, opposing left)
v.arrow(bx + bw / 2, cy, bx + bw / 2 + Fapp / Math.max(fsMax, 1e-6) * 1.8 + 0.05, cy, { color: H.colors.accent, width: 3 });
v.arrow(bx - bw / 2, cy, bx - bw / 2 - friction / Math.max(fsMax, 1e-6) * 1.8 - 0.02, cy, { color: H.colors.warn, width: 3 });
// weight down, normal up
v.arrow(bx, bh, bx, bh - 1.2, { color: H.colors.good, width: 2 });
v.arrow(bx, 0.02, bx, 1.2, { color: H.colors.violet, width: 2 });
H.text("Friction:  f_s ≤ μ_s N,  f_k = μ_k N", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("N = mg = " + N.toFixed(1) + " N    f_s,max = " + fsMax.toFixed(1) + " N    f_k = " + fk.toFixed(1) + " N", 24, 52, { color: H.colors.sub, size: 13 });
H.text((sliding ? "SLIDING — kinetic f_k = " + fk.toFixed(1) + " N" : "STATIC — friction matches push: f = " + friction.toFixed(1) + " N") + "    (push = " + Fapp.toFixed(1) + " N)", 24, H.H - 26, { color: sliding ? H.colors.warn : H.colors.good, size: 14, weight: 700 });
H.legend([{ label: "push F", color: H.colors.accent }, { label: "friction f", color: H.colors.warn }, { label: "weight mg", color: H.colors.good }, { label: "normal N", color: H.colors.violet }], H.W - 160, 28);
